EXAMPLES=[]
for n,q,steps,ans,start,end in [
 ('8','Find the chord length cut by x/a+y/b = 1 on x²+y² = r², and prove the tangent condition a⁻²+b⁻² = r⁻².',['Assume a,b are nonzero real intercepts and r > 0. Multiply the line by ab to get bx+ay−ab = 0.','Its distance from the origin is d = |ab|/√(a²+b²).','For a secant, the perpendicular center-to-chord line bisects the chord. The half-length is √(r²−d²).','Thus |PQ| = 2√(r²−a²b²/(a²+b²)); the radicand must be positive for two distinct intersections.','At tangency d = r, so a²b²/(a²+b²) = r² and the chord shrinks to a single contact point.','Taking reciprocals gives 1/r² = (a²+b²)/(a²b²) = 1/a²+1/b².','This proof uses MP as the half-chord, rather than the source’s mistaken OM label, and also identifies the no-real-intersection case d > r.'],'|PQ| = 2√(r²−a²b²/(a²+b²)); tangent iff a⁻²+b⁻² = r⁻².',224,225),
 ('9','Find the midpoint of the chord cut by x−y+2 = 0 on x²+y²+4x−2y−3 = 0.',['Complete squares: (x+2)²+(y−1)² = 8, giving center C(−2,1) and radius 2√2.','The chord midpoint is the perpendicular projection of C on the line F(x,y) = x−y+2 = 0.','The normal is (1,−1), with squared length 2; F(C) = −2−1+2 = −1.','Therefore M = C−F(C)(1,−1)/2 = (−2,1)+(1/2,−1/2) = (−3/2,1/2).','Check the line: −3/2−1/2+2 = 0.','A chord direction is (1,1); CM = (1/2,−1/2) has dot product zero with it, so CM is perpendicular.','The distance squared CM² = 1/2 is less than r² = 8, confirming a genuine chord. Its symmetric endpoints M±(√15/2)(1,1) have midpoint M and satisfy both original equations.'],'M(−3/2,1/2).',225,225),
 ('10','Find all c for which x+y+c = 0 is tangent to x²+y² = 64, and give the tangent lines and contact points.',['The circle has center (0,0) and radius 8.','The distance from the center to x+y+c = 0 is |c|/√2.','Tangency requires |c|/√2 = 8, hence c = ±8√2.','The contact is the perpendicular projection of the origin onto the line: P = (−c/2,−c/2).','For c = 8√2 the line is x+y+8√2 = 0 and P = (−4√2,−4√2).','For c = −8√2 the line is x+y−8√2 = 0 and P = (4√2,4√2).','Each point has squared norm 32+32 = 64 and makes its own line equation zero. Its radius is parallel to the line normal (1,1), confirming tangency.','The source’s sole positive contact corresponds to the negative constant in its original x+y+c = 0 notation; both branches are required.'],'c = ±8√2; contacts (−c/2,−c/2), namely (−4√2,−4√2) and (4√2,4√2).',226,226)]:
 EXAMPLES.append({'num':n,'title':'Chord and Tangency','question':q,'steps':steps,'answer':ans,'progressiveSolution':True,'solutionOrigin':'SpaceBook learning enhancement','sourceReferences':[{'page':start,'pageEnd':end,'jpg':'116_page_2.jpg' if start==224 else '117_page_1.jpg' if start==225 else '117_page_2.jpg','verification':'Full question, continuation and branch choices visually checked'}],**({'sourceQuestionBlocks':[MIDPOINT]} if n=='9' else {})})
